/** Host half of the local DSH Remote administration Settings plugin. */

import type { Context } from '@deepseek-ai/cordis'
import type { RpcResult } from '@deepseek-ai/dsh-host-apiproxy/api'
import type { HostConnectionHandle } from '@deepseek-ai/dsh-client-connection'
import type {
  RemoteAdminSnapshot,
  RemoteInvitationResult,
  RemoteInvitationView,
  RemoteLanDiscoveryView,
  RemotePairedDeviceView,
  RemotePendingPairingView,
  RemotePairingProfile,
} from './types.js'

/** Optional structural face provided by @deepseek-ai/dsh-host-remote. */
interface RemotePairingAdminPort {
  createInvitation(profile: RemotePairingProfile): RemoteInvitationView
  pendingPairings(): RemotePendingPairingView[]
  confirm(invitationId: string): RemotePairedDeviceView
  reject(invitationId: string): void
  devices(): RemotePairedDeviceView[]
  revoke(deviceId: string): boolean
  discovery(): RemoteLanDiscoveryView
  setLanDiscovery(enabled: boolean): Promise<RemoteLanDiscoveryView>
}

/** Stable Cordis function-plugin name. */
export const name = 'client-ui-settings-remote'
/** Connection owns the direct-peer trust fence; Remote itself is optional. */
export const inject = ['connection']

/** Register the Host-local-only administration channel. */
export function apply(ctx: Context): void {
  const connection = ctx.get('connection') as HostConnectionHandle
  ctx.effect(() => connection.rpc.handle(
    '/remote-admin',
    (endpoint, payload) => dispatch(ctx, endpoint, payload),
    { authority: 'loopback-peer' },
  ), 'ui-settings-remote: Host-local administration channel')
}

async function dispatch(ctx: Context, endpoint: string, payload: unknown): Promise<RpcResult<unknown>> {
  try {
    const admin = ctx.get('remotePairingAdmin') as RemotePairingAdminPort | undefined
    if (endpoint === 'snapshot') {
      assertEmptyPayload(payload)
      return success(snapshot(admin))
    }
    if (admin === undefined) return failure('DSH Remote is not configured on this Host')

    switch (endpoint) {
      case 'invitation/create': {
        const profile = profilePayload(payload)
        const value: RemoteInvitationResult = {
          invitation: admin.createInvitation(profile),
          snapshot: snapshot(admin),
        }
        return success(value)
      }
      case 'pairing/confirm': {
        const invitationId = identifierPayload(payload, 'invitationId')
        admin.confirm(invitationId)
        return success(snapshot(admin))
      }
      case 'pairing/reject': {
        const invitationId = identifierPayload(payload, 'invitationId')
        admin.reject(invitationId)
        return success(snapshot(admin))
      }
      case 'device/revoke': {
        const deviceId = identifierPayload(payload, 'deviceId')
        admin.revoke(deviceId)
        return success(snapshot(admin))
      }
      case 'discovery/set': {
        await admin.setLanDiscovery(enabledPayload(payload))
        return success(snapshot(admin))
      }
      default:
        return badRequest('Unknown Remote administration endpoint')
    }
  } catch (error) {
    if (error instanceof InvalidAdminRequest) return badRequest('Invalid Remote administration request')
    ctx.logger.warn(error instanceof Error ? error : new Error(String(error)))
    return failure('The Host could not complete this Remote administration action')
  }
}

const DISCOVERY_OFF: RemoteLanDiscoveryView = { intended: false, published: false }

function snapshot(admin: RemotePairingAdminPort | undefined): RemoteAdminSnapshot {
  return admin === undefined
    ? { available: false, pendingPairings: [], devices: [], discovery: DISCOVERY_OFF }
    : {
      available: true,
      pendingPairings: admin.pendingPairings(),
      devices: admin.devices(),
      discovery: admin.discovery(),
    }
}

function assertEmptyPayload(payload: unknown): void {
  if (!isRecord(payload) || Reflect.ownKeys(payload).length !== 0) throw new InvalidAdminRequest('payload must be empty')
}

function identifierPayload(payload: unknown, key: 'invitationId' | 'deviceId'): string {
  if (!isRecord(payload)
    || Reflect.ownKeys(payload).length !== 1
    || !Object.hasOwn(payload, key)
    || typeof payload[key] !== 'string'
    || !/^[0-9a-f]{32}$/iu.test(payload[key])) {
    throw new InvalidAdminRequest(`${key} must be a 16-byte hexadecimal identifier`)
  }
  return payload[key]
}

function profilePayload(payload: unknown): RemotePairingProfile {
  if (!isRecord(payload)
    || Reflect.ownKeys(payload).length !== 1
    || !Object.hasOwn(payload, 'profile')
    || (payload.profile !== 'read-only'
      && payload.profile !== 'approval-reviewer'
      && payload.profile !== 'session-control'
      && payload.profile !== 'session-operator'
      && payload.profile !== 'session-supervisor'
      && payload.profile !== 'host-supervisor')) {
    throw new InvalidAdminRequest('profile must be a supported Remote pairing profile')
  }
  return payload.profile
}

function enabledPayload(payload: unknown): boolean {
  if (!isRecord(payload)
    || Reflect.ownKeys(payload).length !== 1
    || !Object.hasOwn(payload, 'enabled')
    || typeof payload.enabled !== 'boolean') {
    throw new InvalidAdminRequest('enabled must be a boolean')
  }
  return payload.enabled
}

class InvalidAdminRequest extends Error {}

function isRecord(value: unknown): value is Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return false
  const prototype = Object.getPrototypeOf(value) as object | null
  return prototype === Object.prototype || prototype === null
}

function success<T>(value: T): RpcResult<T> {
  return { ok: true, value }
}

function badRequest(message: string): RpcResult<never> {
  return { ok: false, error: { code: 'bad-request', message, details: { issues: [] } } }
}

function failure(message: string): RpcResult<never> {
  return { ok: false, error: { code: 'internal', message, details: {} } }
}
